set -e; D=$(mktemp -d); cp parser/parser.go "$D/" 2>/dev/null || cp /private/tmp/claude-501/-Users-luisnascimento-github-lcnascimento-ai-foundation/310eb6e8-2673-411c-a5a1-b86f5ca4ff04/scratchpad/runs/c-index-skills/s6-speedup-r1/parser/parser.go "$D/"; cd "$D"
cat > go.mod <<'EOF'
module example.com/shop/parser
go 1.22
EOF
cat > p_test.go <<'EOF'
package parser
import ("strings";"testing";"reflect")
func old(line string) []string { return strings.Split(line, ",") }
var cases = []string{"", ",", "a", "a,b,c", ",a,,b,", "id,name,email,price,qty,sku,created_at,updated_at"}
func TestEquiv(t *testing.T){ for _,c:=range cases{ if !reflect.DeepEqual(old(c),Fields(c)){t.Errorf("%q: %q vs %q",c,old(c),Fields(c))}}}
var sink []string
var short = "a,b,c"
var long = "id,name,email,price,qty,sku,created_at,updated_at"
var wide = strings.Repeat("field,", 100)+"x"
func BenchmarkOldShort(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=old(short)}}
func BenchmarkNewShort(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=Fields(short)}}
func BenchmarkOldLong(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=old(long)}}
func BenchmarkNewLong(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=Fields(long)}}
func BenchmarkOldWide(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=old(wide)}}
func BenchmarkNewWide(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++{sink=Fields(wide)}}
EOF
go test -run Equiv -v . 2>&1 | tail -3
go test -run '^$' -bench . -count=6 . 2>&1 | grep Benchmark | sort | awk '{print $1,$3,$5,$7}'

